class BowlingGame:
    def __init__(self):
        self.frames = []  # completed frames, each a list of its rolls
        self.current = []  # rolls in the frame in progress
        self.frame = 0  # 0-based index of the frame in progress
        self.complete = False

    def roll(self, pins):
        if pins < 0:
            raise Exception("Rolls cannot score negative points")
        if pins > 10:
            raise Exception("A roll cannot score more than 10 points")
        if self.complete:
            raise Exception("Cannot roll if game already has ten frames")
        if self.frame < 9:
            self._roll_regular_frame(pins)
        else:
            self._roll_tenth_frame(pins)

    def _roll_regular_frame(self, pins):
        if not self.current:
            if pins == 10:
                self._finish_frame([10])
            else:
                self.current = [pins]
        else:
            if self.current[0] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
            self._finish_frame(self.current + [pins])

    def _roll_tenth_frame(self, pins):
        cur = self.current
        if len(cur) == 1:
            if cur[0] < 10 and cur[0] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
        elif len(cur) == 2:
            if cur[1] < 10 and cur[1] + pins > 10:
                raise Exception(
                    "Two bonus rolls after a strike in the last frame "
                    "cannot score more than 10 points"
                )
        cur.append(pins)
        if self._tenth_frame_complete(cur):
            self._finish_frame(cur)

    def _tenth_frame_complete(self, cur):
        if len(cur) == 3:
            return True
        return len(cur) == 2 and cur[0] < 10 and cur[0] + cur[1] < 10

    def _finish_frame(self, rolls):
        self.frames.append(rolls)
        self.current = []
        self.frame += 1
        if self.frame == 10:
            self.complete = True

    def score(self):
        if not self.complete:
            raise Exception("Game is not complete")
        total = 0
        for i, frame in enumerate(self.frames):
            if i < 9:
                if frame[0] == 10:
                    total += 10 + sum(self._next_rolls(i, 2))
                elif len(frame) == 2 and frame[0] + frame[1] == 10:
                    total += 10 + sum(self._next_rolls(i, 1))
                else:
                    total += sum(frame)
            else:
                total += sum(frame)
        return total

    def _next_rolls(self, frame_index, count):
        rolls = []
        i = frame_index + 1
        while len(rolls) < count and i < len(self.frames):
            rolls.extend(self.frames[i])
            i += 1
        return rolls
